16         bool OverlapOnAxis(__m128* a, __m128* b, __m128 axis)
17         {
18             float mx = (std::numeric_limits<float>::max)();
19             float mi = -(std::numeric_limits<float>::max)();
20             __m128 MINMAX = _mm_set_ps(mi, mx, mi, mx);
21             //float min = 0;
22             //min.MaxValue;
23             //float max = 0;
24             //max.MinValue;
25             //float minOther = 0;
26             //minOther.MaxValue;
27             //float maxOther = 0;
28             //maxOther.MinValue;
29             float proj[8];
30             __m128 corner[8];
31             __m128 PROJ[4];
32 
33             {
34                 //__m128 AXIS = axis;
35 
36                 corner[0] = _mm_mul_ps(axis, a[0]);
37                 corner[1] = _mm_mul_ps(axis, a[1]);
38                 corner[2] = _mm_mul_ps(axis, a[2]);
39                 corner[3] = _mm_mul_ps(axis, a[3]);
40                 corner[4] = _mm_mul_ps(axis, a[4]);
41                 corner[5] = _mm_mul_ps(axis, a[5]);
42                 corner[6] = _mm_mul_ps(axis, a[6]);
43                 corner[7] = _mm_mul_ps(axis, a[7]);
44                 //__m128 PROJ[4];
45                 PROJ[0] = _mm_hadd_ps(_mm_hadd_ps(corner[0], corner[1]), _mm_setzero_ps());
46                 PROJ[1] = _mm_hadd_ps(_mm_hadd_ps(corner[2], corner[3]), _mm_setzero_ps());
47                 PROJ[2] = _mm_hadd_ps(_mm_hadd_ps(corner[4], corner[5]), _mm_setzero_ps());
48                 PROJ[3] = _mm_hadd_ps(_mm_hadd_ps(corner[6], corner[7]), _mm_setzero_ps());
49                 //float proj[8]{
50                 //proj[0] = PROJ[0].m128_f32[1],
51                 //  proj[1] = PROJ[0].m128_f32[2],
52                 //  proj[2] = PROJ[1].m128_f32[1],
53                 //  proj[3] = PROJ[1].m128_f32[2],
54                 //  proj[4] = PROJ[2].m128_f32[1],
55                 //  proj[5] = PROJ[2].m128_f32[2],
56                 //  proj[6] = PROJ[3].m128_f32[1],
57                 //  proj[7] = PROJ[3].m128_f32[2],
58                 //  };
59 
60 
61                 __m128 One = _mm_min_ps(PROJ[0], PROJ[1]);
62                 __m128 Two = _mm_min_ps(PROJ[2], PROJ[3]);
63                 __m128 Tree = _mm_min_ps(Two, One);
64                 __m128 Four = _mm_unpacklo_ps(Tree, _mm_setzero_ps());
65                 __m128 Five = _mm_unpackhi_ps(Tree, _mm_setzero_ps());
66                 __m128 Six = _mm_min_ps(Four, Five);
67                 MINMAX.m128_f32[0] = Six.m128_f32[1];
68                 if (Six.m128_f32[0] < Six.m128_f32[1]) {
69                     MINMAX.m128_f32[0] = Six.m128_f32[0];
70                 }
71 
72 
73                 __m128 Seven = _mm_max_ps(PROJ[0], PROJ[1]);
74                 __m128 Eight = _mm_max_ps(PROJ[2], PROJ[3]);
75                 __m128 Nine = _mm_max_ps(Eight, Seven);
76                 __m128 ten = _mm_unpacklo_ps(Nine, _mm_setzero_ps());
77                 __m128 eleven = _mm_unpackhi_ps(Nine, _mm_setzero_ps());
78                 __m128 twelve = _mm_max_ps(eleven, ten);
79                 MINMAX.m128_f32[1] = twelve.m128_f32[1];
80                 if (twelve.m128_f32[1] > twelve.m128_f32[1]) {
81                     MINMAX.m128_f32[1] = twelve.m128_f32[0];
82                 }
83 
84 
85             }
86             {
87                 //__m128 AXIS = axis;
88                 //__m128 corner[8];
89                 corner[0] = _mm_mul_ps(axis, b[0]);
90                 corner[1] = _mm_mul_ps(axis, b[1]);
91                 corner[2] = _mm_mul_ps(axis, b[2]);
92                 corner[3] = _mm_mul_ps(axis, b[3]);
93                 corner[4] = _mm_mul_ps(axis, b[4]);
94                 corner[5] = _mm_mul_ps(axis, b[5]);
95                 corner[6] = _mm_mul_ps(axis, b[6]);
96                 corner[7] = _mm_mul_ps(axis, b[7]);
97                 //__m128 PROJ[4];
98                 PROJ[0] = _mm_hadd_ps(_mm_hadd_ps(corner[0], corner[1]), _mm_setzero_ps());
99                 PROJ[1] = _mm_hadd_ps(_mm_hadd_ps(corner[2], corner[3]), _mm_setzero_ps());
100                 PROJ[2] = _mm_hadd_ps(_mm_hadd_ps(corner[4], corner[5]), _mm_setzero_ps());
101                 PROJ[3] = _mm_hadd_ps(_mm_hadd_ps(corner[6], corner[7]), _mm_setzero_ps());
103                 //proj[0] = PROJ[0].m128_f32[1],
104                 //  proj[1] = PROJ[0].m128_f32[2],
105                 //  proj[2] = PROJ[1].m128_f32[1],
106                 //  proj[3] = PROJ[1].m128_f32[2],
107                 //  proj[4] = PROJ[2].m128_f32[1],
108                 //  proj[5] = PROJ[2].m128_f32[2],
109                 //  proj[6] = PROJ[3].m128_f32[1],
110                 //  proj[7] = PROJ[3].m128_f32[2],
111                 //  //};
112 
113 
114                 __m128 One = _mm_min_ps(PROJ[0], PROJ[1]);
115                 __m128 Two = _mm_min_ps(PROJ[2], PROJ[3]);
116                 __m128 Tree = _mm_min_ps(Two, One);
117                 __m128 Four = _mm_unpacklo_ps(Tree, _mm_setzero_ps());
118                 __m128 Five = _mm_unpackhi_ps(Tree, _mm_setzero_ps());
119                 __m128 Six = _mm_min_ps(Four, Five);
120                 MINMAX.m128_f32[2] = Six.m128_f32[1];
121                 if (Six.m128_f32[2] < Six.m128_f32[1]) {
122                     MINMAX.m128_f32[2] = Six.m128_f32[0];
123                 }
124 
125 
126                 __m128 Seven = _mm_max_ps(PROJ[0], PROJ[1]);
127                 __m128 Eight = _mm_max_ps(PROJ[2], PROJ[3]);
128                 __m128 Nine = _mm_max_ps(Eight, Seven);
129                 __m128 ten = _mm_unpacklo_ps(Nine, _mm_setzero_ps());
130                 __m128 eleven = _mm_unpackhi_ps(Nine, _mm_setzero_ps());
131                 __m128 twelve = _mm_max_ps(eleven, ten);
132                 MINMAX.m128_f32[3] = twelve.m128_f32[1];
133                 if (twelve.m128_f32[3] > twelve.m128_f32[1]) {
134                     MINMAX.m128_f32[3] = twelve.m128_f32[0];
135                 }
136 
137 
138             }
139 
140 
141             //ProjectOntoAxis(a, &axis, &MINMAX,-1);
142             //ProjectOntoAxis(b, &axis, &MINMAX,1);
143 
144             return MINMAX.m128_f32[0] <= MINMAX.m128_f32[3] && MINMAX.m128_f32[1] >= MINMAX.m128_f32[2];
145             //return min <= maxOther && max >= minOther;
146 
147         }
